/* Let enlarged coach text grow above the fixed mobile experiment scene. */
@media(max-width:700px){
  .stage-area{
    height:auto;
    min-height:515px;
    display:grid;
    grid-template-columns:minmax(0,1fr);
    grid-template-rows:minmax(100px,auto) 415px;
  }
  .stage-area:before{
    position:relative;
    inset:auto;
    grid-area:2 / 1;
    margin-top:110px;
    z-index:0;
  }
  .coach{
    position:relative;
    inset:auto;
    grid-area:1 / 1;
    height:auto;
    min-height:100px;
    display:grid;
    grid-template-columns:minmax(0,1fr) 65% 12px;
    grid-template-rows:1fr auto;
    row-gap:3px;
    align-items:start;
    padding:6px 0 2px;
  }
  .coach>div:not(.coach-name):not(#baseline-keepsake){
    position:static;
    grid-column:2;
    grid-row:1;
    width:auto;
  }
  .coach button{
    position:static;
    grid-column:2;
    grid-row:2;
    justify-self:end;
    margin-top:0;
  }
  .coach img{grid-area:auto}
  .coach #baseline-keepsake{grid-area:auto;top:100%}
  .bench{
    position:relative;
    inset:auto;
    grid-area:2 / 1;
    height:415px;
  }
}
